/**
 * Tests for security limits to prevent resource exhaustion attacks.
 */

import { beforeEach, describe, expect, it } from "vitest";
import { Bash } from "./index.js";

describe("Security Limits", () => {
  let bash: Bash;

  beforeEach(() => {
    bash = new Bash();
  });

  describe("maxStringLength limit", () => {
    it("should enforce string length limit on command substitution", async () => {
      // Create a bash env with a very low string length limit
      const limitedBash = new Bash({
        executionLimits: { maxStringLength: 100 },
      });

      // Generate a string that exceeds the limit
      const result = await limitedBash.exec(
        'x=$(printf "%200s" " "); echo "done"',
      );
      expect(result.exitCode).toBe(126); // ExecutionLimitError exit code
      expect(result.stderr).toContain("limit exceeded");
    });

    it("should allow strings within the limit", async () => {
      const limitedBash = new Bash({
        executionLimits: { maxStringLength: 1000 },
      });

      const result = await limitedBash.exec('echo "hello world"');
      expect(result.exitCode).toBe(0);
      expect(result.stdout).toBe("hello world\n");
    });
  });

  describe("maxArrayElements limit", () => {
    it("should enforce array element limit on mapfile", async () => {
      const limitedBash = new Bash({
        executionLimits: { maxArrayElements: 5 },
      });

      // Try to read more lines than allowed using a heredoc
      // Use set -e to exit on first failure
      const result = await limitedBash.exec(`
set -e
mapfile -t arr <<'LINES'
1
2
3
4
5
6
7
LINES
echo "count: \${#arr[@]}"
      `);
      expect(result.exitCode).toBe(1);
      expect(result.stderr).toContain("array element limit exceeded");
    });

    it("should allow arrays within the limit", async () => {
      const limitedBash = new Bash({
        executionLimits: { maxArrayElements: 10 },
      });

      const result = await limitedBash.exec(`
mapfile -t arr <<'LINES'
1
2
3
LINES
echo "count: \${#arr[@]}"
      `);
      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("count: 3");
    });
  });

  describe("maxSubstitutionDepth limit", () => {
    it("should enforce command substitution nesting limit", async () => {
      const limitedBash = new Bash({
        executionLimits: { maxSubstitutionDepth: 3 },
      });

      // Create deeply nested command substitution
      const result = await limitedBash.exec(
        "echo $(echo $(echo $(echo $(echo too-deep))))",
      );
      expect(result.exitCode).toBe(126);
      expect(result.stderr).toContain(
        "Command substitution nesting limit exceeded",
      );
    });

    it("should allow substitution within the limit", async () => {
      const limitedBash = new Bash({
        executionLimits: { maxSubstitutionDepth: 5 },
      });

      const result = await limitedBash.exec("echo $(echo $(echo hello))");
      expect(result.exitCode).toBe(0);
      expect(result.stdout).toBe("hello\n");
    });
  });

  describe("maxGlobOperations limit", () => {
    it("should enforce glob operation limit", async () => {
      // A simple glob like /dir/* requires ~2 operations (entry + readdir)
      // Use limit of 1 to trigger failure on readdir
      const limitedBash = new Bash({
        executionLimits: { maxGlobOperations: 1 },
      });

      // Create some files to glob
      await limitedBash.exec(`
        mkdir -p /tmp/globtest
        touch /tmp/globtest/a /tmp/globtest/b /tmp/globtest/c
      `);

      // Try to glob - this should exceed the low limit on readdir
      const result = await limitedBash.exec("echo /tmp/globtest/*");
      expect(result.exitCode).toBe(126); // ExecutionLimitError exit code
      expect(result.stderr).toContain("Glob operation limit exceeded");
    });

    it("should allow glob operations within the limit", async () => {
      const limitedBash = new Bash({
        executionLimits: { maxGlobOperations: 1000 },
      });

      // Create some files to glob
      await limitedBash.exec(`
        mkdir -p /tmp/globtest2
        touch /tmp/globtest2/a /tmp/globtest2/b /tmp/globtest2/c
      `);

      // Glob should work fine with reasonable limit
      const result = await limitedBash.exec("echo /tmp/globtest2/*");
      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("/tmp/globtest2/a");
    });
  });

  describe("heredoc size limit", () => {
    it("should allow normal heredocs", async () => {
      const result = await bash.exec(`
        cat <<EOF
        This is a normal heredoc
        with multiple lines
        EOF
      `);
      expect(result.exitCode).toBe(0);
      expect(result.stdout).toContain("This is a normal heredoc");
    });
  });

  describe("null byte validation in filesystem", () => {
    it("should reject paths with null bytes", async () => {
      const result = await bash.exec('cat "/etc\\x00/passwd"');
      expect(result.exitCode).not.toBe(0);
    });
  });
});

import { describe, expect, it } from "vitest";
import { Bash } from "../../Bash.js";

describe("find actions", () => {
  describe("-exec {} + (batch mode)", () => {
    it("should execute command once with all files", async () => {
      const env = new Bash({
        files: {
          "/dir/a.txt": "aaa",
          "/dir/b.txt": "bbb",
          "/dir/c.txt": "ccc",
        },
      });
      const result = await env.exec(
        'find /dir -type f -name "*.txt" -exec cat {} +',
      );
      // All files should be passed to cat at once - output is concatenated
      expect(result.stdout).toBe("aaabbbccc");
      expect(result.stderr).toBe("");
      expect(result.exitCode).toBe(0);
    });

    it("should work with wc -l to count all lines at once", async () => {
      const env = new Bash({
        files: {
          "/dir/a.txt": "line1\nline2\n",
          "/dir/b.txt": "line1\nline2\nline3\n",
        },
      });
      const result = await env.exec(
        'find /dir -type f -name "*.txt" -exec wc -l {} +',
      );
      // wc -l with multiple files shows per-file counts and total
      expect(result.stdout).toBe(`  2 /dir/a.txt
  3 /dir/b.txt
  5 total
`);
      expect(result.stderr).toBe("");
      expect(result.exitCode).toBe(0);
    });

    it("should pass multiple files to grep", async () => {
      const env = new Bash({
        files: {
          "/dir/a.txt": "hello world",
          "/dir/b.txt": "hello there",
          "/dir/c.txt": "goodbye",
        },
      });
      const result = await env.exec(
        "find /dir -type f -exec grep -l hello {} +",
      );
      expect(result.stdout).toBe("/dir/a.txt\n/dir/b.txt\n");
      expect(result.stderr).toBe("");
      expect(result.exitCode).toBe(0);
    });
  });

  describe("-exec {} ; (single file mode)", () => {
    it("should execute command for each file separately", async () => {
      const env = new Bash({
        files: {
          "/dir/a.txt": "aaa",
          "/dir/b.txt": "bbb",
        },
      });
      // Using echo to see each file is processed separately
      const result = await env.exec(
        'find /dir -type f -name "*.txt" -exec echo FILE: {} \\;',
      );
      expect(result.stdout).toBe("FILE: /dir/a.txt\nFILE: /dir/b.txt\n");
      expect(result.stderr).toBe("");
      expect(result.exitCode).toBe(0);
    });
  });

  describe("-print0", () => {
    it("should output null-terminated filenames", async () => {
      const env = new Bash({
        files: {
          "/dir/a.txt": "a",
          "/dir/b.txt": "b",
        },
      });
      const result = await env.exec('find /dir -type f -name "*.txt" -print0');
      expect(result.stdout).toBe("/dir/a.txt\0/dir/b.txt\0");
      expect(result.stderr).toBe("");
      expect(result.exitCode).toBe(0);
    });

    it("should work with xargs -0", async () => {
      const env = new Bash({
        files: {
          "/dir/file with spaces.txt": "content",
          "/dir/normal.txt": "content",
        },
      });
      const result = await env.exec(
        "find /dir -type f -print0 | xargs -0 echo",
      );
      expect(result.stdout).toBe("/dir/file with spaces.txt /dir/normal.txt\n");
      expect(result.stderr).toBe("");
      expect(result.exitCode).toBe(0);
    });
  });

  describe("-delete", () => {
    it("should delete found files", async () => {
      const env = new Bash({
        files: {
          "/dir/a.txt": "a",
          "/dir/b.txt": "b",
          "/dir/keep.md": "keep",
        },
      });
      await env.exec('find /dir -type f -name "*.txt" -delete');

      // Check that .txt files are gone
      const result = await env.exec("ls /dir");
      expect(result.stdout).toBe("keep.md\n");
      expect(result.stderr).toBe("");
    });

    it("should delete empty directories", async () => {
      const env = new Bash({
        files: {
          "/dir/subdir/.keep": "",
        },
      });
      // First delete the file, then the empty directory
      await env.exec("rm /dir/subdir/.keep");
      await env.exec("find /dir -type d -empty -delete");

      const result = await env.exec("ls /dir");
      expect(result.stdout).toBe("");
      expect(result.stderr).toBe("");
    });

    it("should not delete non-empty directories", async () => {
      const env = new Bash({
        files: {
          "/dir/subdir/file.txt": "content",
        },
      });
      const result = await env.exec("find /dir -type d -name subdir -delete");
      // Should fail because directory is not empty
      expect(result.exitCode).toBe(1);
      expect(result.stderr).toBe(
        "find: cannot delete '/dir/subdir': ENOTEMPTY: directory not empty, rm '/dir/subdir'\n",
      );
    });

    it("should delete files sorted by depth (deepest first)", async () => {
      const env = new Bash({
        files: {
          "/dir/a.txt": "a",
          "/dir/sub/b.txt": "b",
          "/dir/sub/deep/c.txt": "c",
        },
      });
      // Delete all .txt files - should work because files are deleted deepest-first
      await env.exec('find /dir -name "*.txt" -delete');

      const result = await env.exec("find /dir -type f");
      expect(result.stdout).toBe("");
      expect(result.stderr).toBe("");
      expect(result.exitCode).toBe(0);
    });
  });

  describe("-print (explicit)", () => {
    it("should only print when -print is reached in expression", async () => {
      const env = new Bash({
        files: {
          "/dir/a.txt": "a",
          "/dir/b.md": "b",
        },
      });
      // Only print .txt files explicitly
      const result = await env.exec('find /dir -name "*.txt" -print');
      expect(result.stdout).toBe("/dir/a.txt\n");
      expect(result.stderr).toBe("");
      expect(result.exitCode).toBe(0);
    });

    it("should work with OR and selective printing", async () => {
      const env = new Bash({
        files: {
          "/dir/a.txt": "a",
          "/dir/b.md": "b",
          "/dir/c.json": "c",
        },
      });
      // Complex expression: print .txt OR process .md silently
      const result = await env.exec(
        'find /dir -name "*.txt" -print -o -name "*.md"',
      );
      // Only .txt files are printed because -print is in that branch
      expect(result.stdout).toBe("/dir/a.txt\n");
      expect(result.stderr).toBe("");
      expect(result.exitCode).toBe(0);
    });
  });
});

import { describe, expect, it, vi } from "vitest";
import {
  createConsoleViolationCallback,
  SecurityViolationLogger,
} from "./security-violation-logger.js";
import type { SecurityViolation } from "./types.js";

describe("SecurityViolationLogger", () => {
  const createTestViolation = (
    overrides: Partial<SecurityViolation> = {},
  ): SecurityViolation => ({
    timestamp: Date.now(),
    type: "function_constructor",
    message: "Test violation",
    path: "globalThis.Function",
    stack: "Error\n    at test.ts:1:1",
    executionId: "test-exec-id",
    ...overrides,
  });

  describe("recording violations", () => {
    it("should record violations", () => {
      const logger = new SecurityViolationLogger();
      const violation = createTestViolation();

      logger.record(violation);

      expect(logger.getTotalCount()).toBe(1);
      expect(logger.hasViolations()).toBe(true);
    });

    it("should return violations in reverse order (most recent first)", () => {
      const logger = new SecurityViolationLogger();

      logger.record(createTestViolation({ message: "first" }));
      logger.record(createTestViolation({ message: "second" }));
      logger.record(createTestViolation({ message: "third" }));

      const violations = logger.getViolations();
      expect(violations[0].message).toBe("third");
      expect(violations[1].message).toBe("second");
      expect(violations[2].message).toBe("first");
    });

    it("should group violations by type", () => {
      const logger = new SecurityViolationLogger();

      logger.record(createTestViolation({ type: "function_constructor" }));
      logger.record(createTestViolation({ type: "eval" }));
      logger.record(createTestViolation({ type: "function_constructor" }));

      const fnViolations = logger.getViolationsByType("function_constructor");
      const evalViolations = logger.getViolationsByType("eval");

      expect(fnViolations.length).toBe(2);
      expect(evalViolations.length).toBe(1);
    });

    it("should cap violations per type", () => {
      const logger = new SecurityViolationLogger({ maxViolationsPerType: 3 });

      for (let i = 0; i < 10; i++) {
        logger.record(createTestViolation({ message: `violation ${i}` }));
      }

      const byType = logger.getViolationsByType("function_constructor");
      expect(byType.length).toBe(3);
    });
  });

  describe("stack trace handling", () => {
    it("should include stack traces by default", () => {
      const logger = new SecurityViolationLogger();
      const violation = createTestViolation({ stack: "test stack" });

      logger.record(violation);

      const recorded = logger.getViolations()[0];
      expect(recorded.stack).toBe("test stack");
    });

    it("should strip stack traces when configured", () => {
      const logger = new SecurityViolationLogger({ includeStackTraces: false });
      const violation = createTestViolation({ stack: "test stack" });

      logger.record(violation);

      const recorded = logger.getViolations()[0];
      expect(recorded.stack).toBeUndefined();
    });
  });

  describe("custom handlers", () => {
    it("should call onViolation callback", () => {
      const onViolation = vi.fn();
      const logger = new SecurityViolationLogger({ onViolation });
      const violation = createTestViolation();

      logger.record(violation);

      expect(onViolation).toHaveBeenCalledTimes(1);
      expect(onViolation).toHaveBeenCalledWith(violation);
    });

    it("should provide createCallback() method", () => {
      const logger = new SecurityViolationLogger();
      const callback = logger.createCallback();

      callback(createTestViolation());

      expect(logger.getTotalCount()).toBe(1);
    });
  });

  describe("console logging", () => {
    it("should log to console when enabled", () => {
      const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
      const logger = new SecurityViolationLogger({ logToConsole: true });

      logger.record(createTestViolation({ message: "test message" }));

      expect(warnSpy).toHaveBeenCalled();
      expect(warnSpy.mock.calls[0][0]).toContain("SecurityViolation");

      warnSpy.mockRestore();
    });

    it("should not log to console by default", () => {
      const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
      const logger = new SecurityViolationLogger();

      logger.record(createTestViolation());

      expect(warnSpy).not.toHaveBeenCalled();

      warnSpy.mockRestore();
    });
  });

  describe("summary generation", () => {
    it("should generate summary by type", () => {
      const logger = new SecurityViolationLogger();

      const now = Date.now();
      logger.record(
        createTestViolation({
          type: "function_constructor",
          path: "globalThis.Function",
          timestamp: now - 1000,
        }),
      );
      logger.record(
        createTestViolation({
          type: "function_constructor",
          path: "globalThis.Function",
          timestamp: now,
        }),
      );
      logger.record(
        createTestViolation({
          type: "eval",
          path: "globalThis.eval",
          timestamp: now - 500,
        }),
      );

      const summary = logger.getSummary();

      expect(summary.length).toBe(2);

      // Should be sorted by count descending
      expect(summary[0].type).toBe("function_constructor");
      expect(summary[0].count).toBe(2);
      expect(summary[0].firstSeen).toBe(now - 1000);
      expect(summary[0].lastSeen).toBe(now);
      expect(summary[0].paths).toContain("globalThis.Function");

      expect(summary[1].type).toBe("eval");
      expect(summary[1].count).toBe(1);
    });

    it("should deduplicate paths in summary", () => {
      const logger = new SecurityViolationLogger();

      logger.record(createTestViolation({ path: "globalThis.Function" }));
      logger.record(createTestViolation({ path: "globalThis.Function" }));
      logger.record(createTestViolation({ path: "globalThis.Function" }));

      const summary = logger.getSummary();
      expect(summary[0].paths.length).toBe(1);
    });
  });

  describe("clearing", () => {
    it("should clear all violations", () => {
      const logger = new SecurityViolationLogger();

      logger.record(createTestViolation());
      logger.record(createTestViolation({ type: "eval" }));

      expect(logger.getTotalCount()).toBe(2);

      logger.clear();

      expect(logger.getTotalCount()).toBe(0);
      expect(logger.hasViolations()).toBe(false);
      expect(logger.getViolations()).toEqual([]);
      expect(logger.getSummary()).toEqual([]);
    });
  });
});

